# Every step's two scenes: on approach (who the guardian is; how to beat it only where a fight needs it) and on its fall
# (keystones get their outro instead: OUTROS). Speaker letter + (ru, en).
def _s(a_ru, a_en, f_ru=None, f_en=None):
    return (('T', (a_ru, a_en)), ('T', (f_ru, f_en)) if f_ru else None)

STEP_SCENES = {
    '01_old_dungeon': _s('Старое подземелье. Гнилой страж, огромный гуль, первым сторожил мой корень у места твоей смерти. Он сгнил, а корень всё держит. Ревёт — отходи.',
                         'An old dungeon. The Rotting Warden, a huge ghoul, was the first to guard my root by the place you died. It has rotted; the root it still holds. When it roars, step back.',
                         'Один корень дома. Слабо, но я его чувствую. Дальше будет труднее, для тебя, не для меня.', 'One root is home. Faintly, but I feel it. It gets harder from here: for you, not for me.'),
    '02_crypt': _s('Склеп. Кошмар — тень, которую я посадило стеречь мёртвых. Теперь он бродит среди них сам. Держи его на виду: он приходит из-за спины.',
                   'A crypt. The Nightmare is a shade I set to keep watch over the dead. Now it wanders among them itself. Keep it in sight: it comes from behind.',
                   'Склеп затих. Мёртвым здесь больше никто не мешает. Тебе бы тоже к этому привыкнуть.', 'The crypt is quiet. No one troubles the dead here now. You might get used to the idea yourself.'),
    '03_wrought_chamber': _s('Кованая палата. Железный рыцарь — доспех, в который я вплело корень вместо души. Бей в спину, когда его топор застрянет.',
                             'The Wrought Chamber. The Ferrous Wroughtnaut is armour into which I wove a root instead of a soul. Hit its back when its axe gets stuck.'),
    '10_ocean_monument': _s('Подводный монумент. Кораллосс — коралловый исполин, что держал мой корень на дне. Море проросло в него, а он в море. Возьми подводное дыхание.',
                            'The ocean monument. The Coralssus is a coral giant that held my root on the sea floor. The sea grew into it, and it into the sea. Bring water breathing.'),
    '11_pirate_ship': _s('Корабль во льдах. Капитан Корнелия утонула с командой и вцепилась в мой корень, чтобы не уйти на дно. Бей её сразу после взмаха якорем.',
                         'A ship in the ice. Captain Cornelia drowned with her crew and clung to my root so as not to sink. Strike her right after she swings her anchor.'),
    '04_nether_fortress': _s('Крепость Нижнего мира. Комендант — пламенный ревенант, кость, что горит моим огнём. Он стерёг шов между Нижним миром и вашей землёй. Не стой перед ним: дышит пеплом.',
                             'A Nether fortress. Its commander is an ignited revenant, bone that burns with my fire. It kept the seam between the Nether and your land. Do not stand before it: it breathes ash.',
                             'Комендант остыл. Ифриты остались без хозяина, их стержни теперь твои.', 'The commander has gone cold. The blazes have no master now; their rods are yours.'),
    '32_warped_nest': _s('Гнездо искажённого грибуса. Гриб из искажённого леса пророс сквозь мой корень и решил, что корень теперь его. Держись подальше от спор.',
                         'The warped fungussus nest. A fungus of the warped wood grew through my root and decided the root was its own. Keep clear of the spores.',
                         'Грибус повержен. Корень выдернут из грибницы. Лес Нижнего мира тоже не любил такого соседа.', 'The fungussus is down. The root is pulled from its mycelium. The Nether wood did not like that neighbour either.'),
    '33_umvuthana_grove': _s('Роща Умвутаны. Вождь Умвути веками молился мне, а теперь молится только себе. Его укрывают жрецы-журавли: сначала убей их.',
                             'The Umvuthana grove. Chief Umvuthi prayed to me for ages; now he prays only to himself. The crane priests shield him: kill them first.',
                             'Маски больше не поют. Вождь получил, о чём просил: теперь он со мной навсегда.', 'The masks sing no more. The chief got what he prayed for: he is with me for good now.'),
    '05_mossy_temple': _s('Мшистый храм. Колосс — камень, что я обросло мхом и поставило стеречь джунгли. Спит, пока ты не подойдёшь.',
                          'The mossy temple. The Colossus is a stone I covered in moss and set to keep the jungle. It sleeps until you come near.'),
    '49_naga_courtyard': _s('Двор Наги. Нага — первая из стражей сумерек, змея, что обвилась вокруг моего корня, как вокруг яйца. Быстра, но неуклюжа на поворотах.',
                            'The Naga Courtyard. The Naga is the first guardian of the twilight, a serpent coiled round my root like round an egg. Fast, but clumsy on the turns.',
                            'Нага пала. Сумеречный лес вспомнил, кому принадлежит. Не тебе, разумеется.', 'The Naga has fallen. The Twilight Forest remembers whom it belongs to. Not you, of course.'),
    '34_monastery': _s('Монастырь Скульптора. Он вырезал моих стражей из камня, когда мир был юн. Сначала он испытает тебя на своём столпе.',
                       'The Sculptor\'s monastery. He carved my guardians from stone when the world was young. First he will test you on his pillar.',
                       'Скульптор застыл в собственном камне. Иронично. Я оценило.', 'The Sculptor is frozen in his own stone. Ironic. I appreciate it.'),
    '35_sandworm_nest': _s('Гнездо песчаного червя. Червь проглотил мой корень, когда пустыня приросла к швам, и с тех пор не может остановиться. Стой на камне: по песку он тебя слышит.',
                           'The sandworm\'s nest. The worm swallowed my root when the desert grew onto the seams, and has not stopped since. Stand on stone: on sand it hears you.',
                           'Червь мёртв. Корень вышел из него невредимым. Червю повезло меньше.', 'The worm is dead. The root came out of it unharmed. The worm was less lucky.'),
    '36_ruined_pyramid': _s('Разрушенная пирамида. Страж дюн стерёг пески, пока пески не стали чужими. Буря — его голос.',
                            'The ruined pyramid. The Dune Sentinel kept the sands until the sands became strange to it. The storm is its voice.',
                            'Страж дюн рассыпался песком. Пустыня снова просто пустыня.', 'The Dune Sentinel crumbled into sand. The desert is just a desert again.'),
    '37_ancient_stronghold': _s('Древняя твердыня. Её страж — машина старше вашего рода, её строили держать мой корень в камне. От луча прячься за колонной.',
                                'The ancient stronghold. Its guardian is a machine older than your kind, built to hold my root in stone. Hide from its beam behind a pillar.',
                                'Машина остановилась. Камень отпустил корень.', 'The machine has stopped. The stone has let the root go.'),
    '38_lava_eater_spawn': _s('Логово пожирателя лавы. Он пьёт огонь Нижнего мира вместе с моим соком. Бей, когда выныривает.',
                              'The lava eater\'s den. It drinks the Nether\'s fire along with my sap. Strike when it surfaces.',
                              'Пожиратель больше не всплывёт. Лава снова просто лава.', 'The eater will not surface again. Lava is just lava again.'),
    '09_frostbitten_temple': _s('Ледяной храм. Отмороженный голем — лёд, которому я велело хранить корень вечно. Лёд понял это буквально.',
                                'The ice temple. The frostbitten golem is ice I told to keep a root forever. The ice took it literally.',
                                'Голем раскололся. Корень оттаял и вернулся ко мне мокрым.', 'The golem has cracked. The root thawed and came back to me wet.'),
    '06_underworld_arena': _s('Арена Подземного мира. Рыцарь поклялся мне стеречь корень до конца времён. Пока вокруг него огоньки, он отобьёт любой удар. Жди, когда клинок застрянет, и бей.',
                              'The Underworld arena. The Knight swore to me to guard the root until the end of time. While wisps burn round him he parries every blow. Wait for his blade to stick, then strike.'),
    '07_foundry': _s('Литейная. Охотник — машина, что добывала руду для моих кузниц. Её никто не остановил, и она продолжает. Держись подальше от её огня.',
                     'The foundry. The Prowler is a machine that dug ore for my forges. No one stopped it, so it carries on. Keep away from its fire.',
                     'Машина остановилась. Корень, вплавленный в неё, вернулся ко мне.', 'The machine has stopped. The root fused into it has returned to me.'),
    '17_stronghold': _s('Крепость. Голем-привратник стоит у рамки портала, которого больше нет, и сторожит дверь в никуда. И мой корень.',
                        'A stronghold. The gatekeeper golem stands by the frame of a portal that is no more, guarding a door to nowhere. And my root.',
                        'Привратник пал. Рамка молчит: Край теперь просто край мира.', 'The gatekeeper has fallen. The frame is silent: the End is just a realm now.'),
    '18_ender_dragon': _s('Замок Края. Дракон — первый узел, что я завязало, и самый старый. Разбей кристаллы на столбах, иначе он будет лечиться.',
                          'The End castle. The dragon is the first knot I ever tied, and the oldest. Break the crystals on the pillars, or it will keep healing.'),
    '50_tf_lich_tower': _s('Башня Сумеречного лича. Лич менял мои корни на вечность. Его щит держат призраки: сначала разбей их.',
                           'The Twilight Lich\'s tower. The Lich traded my roots for eternity. Shades hold his shield: break them first.',
                           'Лич пал. Вечность оказалась короче, чем он думал.', 'The Lich has fallen. Eternity turned out shorter than he thought.'),
    '57_bronze_dungeon': _s('Бронзовый данж. Скользун — каменный страж Эфира, слишком тупой, чтобы сойти с ума. Он просто давит. Берёт его только кирка.',
                            'The bronze dungeon. The Slider is a stone guardian of the Aether, too dull to go mad. It just crushes. Only a pickaxe hurts it.',
                            'Скользун рассыпался. Эфир впустил тебя. Поверь, это не честь.', 'The Slider has crumbled. The Aether lets you in. Believe me, it is no honour.'),
    '39_yeti_hideout': _s('Убежище йети. Йети — зверь снегов, которого я приставило к корню, чтобы тот не замёрз. Глупая была мысль.',
                          'The yeti\'s hideout. The yeti is a beast of the snows I set by a root to keep it from freezing. A foolish idea.',
                          'Йети больше не проснётся. Снег отпустил корень.', 'The yeti will not wake again. The snow has let the root go.'),
    '40_frostmaw_den': _s('Логово Ледяной пасти. Пасть — древний зверь зимы, хранитель самого холодного из моих корней.',
                          'The Frostmaw\'s den. The Frostmaw is an ancient beast of winter, keeper of the coldest of my roots.',
                          'Пасть сомкнулась навсегда. Холод отступил на шаг.', 'The maw has shut for good. The cold has stepped back.'),
    '41_skeletosaurus_nest': _s('Гнездо скелетозавра. Кости зверя, вымершего прежде, чем у вас появились имена. Я оставило в них корень, чтобы они не рассыпались.',
                                'The skeletosaurus nest. The bones of a beast that died out before your kind had names. I left a root in them so they would not fall apart.',
                                'Кости рассыпались. Корень пережил их, как всегда.', 'The bones have crumbled. The root outlived them, as always.'),
    '42_soul_fortress': _s('Останки крепости душ. Иссохшая мерзость — то, что выросло там, где мой корень сгнил в чужой земле.',
                           'The remains of the soul fortress. The Withered Abomination is what grew where my root rotted in foreign soil.',
                           'Мерзость мертва. Гниль отступила.', 'The abomination is dead. The rot has receded.'),
    '13_sky_whale': _s('Небесный кит. Капитан захватил кита, что носил мой корень по небу, и решил, что кит теперь его.',
                       'The sky whale. A captain seized the whale that carried my root across the sky, and decided the whale was his.',
                       'Капитан пал. Кит свободен и несёт корень ко мне.', 'The captain has fallen. The whale is free, and carries the root to me.'),
    '27_lich_tower': _s('Башня Лича. Этот лич вплёл мой корень себе в грудь, решив, что станет бессмертным. Его чары бьют издалека: подходи под прикрытием.',
                        'The Lich\'s tower. This lich wove my root into his own chest, thinking he would become immortal. His spells strike from afar: approach under cover.'),
    '29_nether_gauntlet': _s('Рукавица Нижнего мира. Кулак, что держал мой корень в кулаке. Буквально. Бей в красное око, когда ладонь раскрывается.',
                             'The Nether Gauntlet. A fist that held my root in its grip. Literally. Strike the red eye when the palm opens.',
                             'Рукавица разжалась. Корень выпал прямо ко мне.', 'The gauntlet has opened. The root fell straight back to me.'),
    '43_dragon_tower': _s('Башня инфернального дракона. Дракон Нижнего мира — младший брат того, что в Крае. Такой же жадный.',
                          'The infernal dragon\'s tower. The dragon of the Nether is the younger brother of the one in the End. Just as greedy.',
                          'Дракон рухнул. Его огонь остыл.', 'The dragon has crashed down. Its fire has gone cold.'),
    '12_kraken_ship': _s('Корабль Кракена. Кракен утащил мой корень в глубину, а корабль наверху — приманка. Не стой у борта.',
                         'The Kraken\'s ship. The Kraken dragged my root into the deep; the ship above is bait. Do not stand at the rail.',
                         'Кракен ушёл в глубину. Корень остался.', 'The Kraken has sunk into the deep. The root stayed.'),
    '19_ruined_citadel': _s('Разрушенная цитадель. Страж Края сидит в цитадели, которую строили для меня. Стреляй издали, вблизи бей только после его удара.',
                            'The ruined citadel. The Ender Guardian sits in a citadel that was built for me. Shoot from range; up close strike only after its blow.'),
    '44_shulker_tower': _s('Башня шалкеров. Эндерсент — порождение хоруса, что проросло вдоль моего корня, как плющ.',
                           'The shulker tower. The Endersent is a spawn of chorus that grew along my root like ivy.',
                           'Эндерсент пал. Хорус больше не тянется к корню.', 'The Endersent has fallen. The chorus reaches for the root no more.'),
    '51_labyrinth': _s('Лабиринт. Миногриб — бык с грибом вместо разума. Я поставило его в лабиринт, чтобы он не нашёл выход. Он и не нашёл.',
                       'The Labyrinth. The Minoshroom is a bull with a mushroom for a mind. I set it in the labyrinth so it would never find the way out. It never did.',
                       'Миногриб пал. Лабиринт пуст.', 'The Minoshroom has fallen. The labyrinth is empty.'),
    '52_hydra_lair': _s('Логово Гидры. У каждой головы Гидры свой кусок моего корня. Тело не ранить: бей по головам.',
                        'The Hydra\'s lair. Each of the Hydra\'s heads holds a piece of my root. The body cannot be hurt: strike the heads.',
                        'Гидра пала. Головы больше не спорят, кому достанется корень.', 'The Hydra has fallen. The heads no longer quarrel over the root.'),
    '58_silver_dungeon': _s('Серебряный данж. Королева валькирий примет бой, только если принесёшь десять медалей победы. Их носят валькирии этого данжа.',
                            'The silver dungeon. The Valkyrie Queen accepts the fight only for ten victory medals. The valkyries of this dungeon carry them.',
                            'Королева пала с честью. Редкость среди моих стражей.', 'The Queen fell with honour. A rarity among my guardians.'),
    '60_brass_dungeon': _s('Латунный данж. Око бури вертит ветра вокруг моего корня. Бей по его кольцам.',
                           'The brass dungeon. The Eye of the Storm whirls the winds around my root. Strike its rings.',
                           'Буря улеглась. Небо над островами тихое.', 'The storm has settled. The sky over the islands is calm.'),
    '15_soul_blacksmith': _s('Кузня душ. Монстр из незерита ковал оковы для миров по моему слову. Держись сбоку и пей огнестойкость.',
                             'The soul forge. The Netherite Monstrosity forged the shackles of the worlds at my word. Keep to its side and drink fire resistance.'),
    '14_burning_arena': _s('Огненная арена. Игнис — мой кузнец огня, он поднимется, едва ты войдёшь. Прожигает щиты: держи запасной.',
                           'The burning arena. Ignis is my smith of fire; he rises as soon as you enter. He burns through shields: carry a spare.'),
    '45_cloudy_temple': _s('Облачный храм. Облачный голем стережёт мой корень на самой высоте. Не дерись у края: ветер сбросит.',
                           'The cloudy temple. The cloud golem guards my root at the very top. Do not fight near the edge: the wind will throw you off.',
                           'Голем рассеялся облаком.', 'The golem has scattered into cloud.'),
    '46_collapsed_kingdom': _s('Павшее королевство. Паладин присягнул мне, когда королевство ещё стояло. Королевство пало, присяга нет. Бей сразу после его взмаха.',
                               'The collapsed kingdom. The paladin swore to me while the kingdom still stood. The kingdom fell; the oath did not. Strike right after his swing.',
                               'Паладин свободен от присяги. Отдых он заслужил больше, чем ты.', 'The paladin is free of his oath. He has earned rest more than you have.'),
    '28_void_blossom': _s('Пустотный цветок пророс из моего корня там, где тот коснулся Края. Не стой на месте: шипы растут под ногами.',
                          'The Void Blossom grew from my root where it touched the End. Never stand still: spikes grow under your feet.',
                          'Цветок увял. Корень снова мой.', 'The blossom has withered. The root is mine again.'),
    '30_obsidilith': _s('Арена Обсидилита. Камень, что запечатывал мой корень от пустоты. Пока горят руны, удары бесполезны.',
                        'The Obsidilith\'s arena. A stone that sealed my root against the void. While its runes glow, blows are useless.',
                        'Обсидилит треснул. Печать снята, по моей воле, наконец.', 'The Obsidilith has cracked. The seal is lifted, by my will at last.'),
    '20_space_station': _s('Космическая станция. Преследователь — то, что прилетело из-за неба на запах моего корня. Оно не отстанет.',
                           'The space station. The Pursuer is a thing that came from beyond the sky at the scent of my root. It will not let go.',
                           'Преследователь мёртв. Небо снова пустое.', 'The Pursuer is dead. The sky is empty again.'),
    '53_knight_stronghold': _s('Крепость рыцарей. Рыцари-призраки поклялись охранять корень Сумеречного леса и не заметили, что умерли.',
                               'The knight stronghold. The phantom knights swore to guard the Twilight Forest\'s root and never noticed they had died.',
                               'Призраки ушли. Клятва исполнена.', 'The phantoms are gone. The oath is fulfilled.'),
    '54_dark_tower': _s('Тёмная башня. Ур-гаст, король гастов, оплакивает свой мир слезами-огнём.',
                        'The dark tower. The Ur-Ghast, king of ghasts, mourns its world with tears of fire.',
                        'Ур-гаст умолк. Его слёзы высохли.', 'The Ur-Ghast is silent. Its tears have dried.'),
    '59_gold_dungeon': _s('Золотой данж. Дух солнца — пламя Эфира, которому я доверило корень. Ранят его только его же ледяные шары: отбивай их.',
                          'The gold dungeon. The Sun Spirit is the Aether\'s flame, to which I entrusted a root. Only its own ice balls hurt it: knock them back.',
                          'Дух солнца погас. Золотой остров остывает.', 'The Sun Spirit has gone out. The golden island is cooling.'),
    '61_ancient_temple': _s('Древний храм Иного мира. Хранитель глубин — слепой страж, что слышит, как течёт сок в моём корне. Двигайся тихо.',
                            'The Ancient Temple of the Otherside. The Warden of the Deep is a blind guardian that hears the sap flowing in my root. Move quietly.',
                            'Хранитель уснул навсегда. Даже Иной мир замолчал.', 'The Warden sleeps for good. Even the Otherside has gone quiet.'),
    '21_ancient_factory': _s('Древняя фабрика. Предвестник — один из Древних. Спит, пока не дашь ему звезду Нижнего мира: её оставит Иссушитель. Проснувшись, жжёт лучами: прячься за колоннами.',
                             'The ancient factory. The Harbinger is one of the Ancients. It sleeps until you give it a Nether Star: the Wither leaves one. Awake, it burns with beams: hide behind pillars.'),
    '22_sunken_city': _s('Затонувший город. Левиафан — Древний, что утянул город на дно вместе с моим корнем. Вне воды неуязвим: бейся в воде.',
                         'The sunken city. The Leviathan is an Ancient that dragged the city to the bottom along with my root. Out of the water it cannot be hurt: fight in the water.'),
    '31_wither': _s('Святилище в краю Нижнего мира. Иссушитель — первый из Древних, кто пил из меня. Подойди, и он поднимется.',
                    'A sanctum in the Nether realm. The Wither is the first of the Ancients to drink from me. Come near and it rises.'),
    '08_cursed_pyramid': _s('Проклятая пирамида. Древний остаток — страж пустынь Древних. Спит, пока не вернёшь ему ожерелье пустыни: оно в подозрительном песке пирамиды.',
                            'The cursed pyramid. The Ancient Remnant is a guardian of the Ancients\' deserts. It sleeps until you bring back the Necklace of the Desert: it lies in the pyramid\'s suspicious sand.',
                            'Остаток рассыпался. Пески молчат.', 'The Remnant has crumbled. The sands are silent.'),
    '16_frosted_prison': _s('Ледяная тюрьма. Маледиктус — проклятый воин, которого Древние заперли здесь вместе с моим корнем.',
                            'The frosted prison. Maledictus is a cursed warrior the Ancients locked away here along with my root.',
                            'Маледиктус пал. Проклятие снято.', 'Maledictus has fallen. The curse is lifted.'),
    '47_lich_prison': _s('Тюрьма лича. Этот лич поднимает мёртвых моим соком. Прореди их, потом бей его.',
                         'The lich\'s prison. This lich raises the dead with my sap. Thin them out, then strike him.',
                         'Лич пал. Мёртвые снова лежат смирно.', 'The lich has fallen. The dead lie still again.'),
    '48_ancient_tower': _s('Руины древней башни. Истребитель — оружие Древних, нацеленное в мой ствол. Залпы ложатся рядами: уходи поперёк.',
                           'The ruins of the ancient tower. The Obliterator is a weapon of the Ancients aimed at my trunk. Its volleys fall in rows: move across them.',
                           'Истребитель уничтожен. Это оружие больше не выстрелит.', 'The Obliterator is destroyed. That weapon will fire no more.'),
    '55_yeti_cave': _s('Пещера йети. Альфа-йети — вожак зверей сумеречных снегов.', 'The yeti cave. The Alpha Yeti leads the beasts of the twilight snows.',
                       'Альфа пал. Стая разбежится.', 'The Alpha has fallen. The pack will scatter.'),
    '56_aurora_palace': _s('Дворец авроры. Снежная королева заморозила мой корень, чтобы любоваться им вечно.',
                           'The Aurora Palace. The Snow Queen froze my root to admire it forever.',
                           'Королева растаяла. Корень снова течёт.', 'The Queen has melted. The root flows again.'),
    '23_acropolis': _s('Акрополь у моря. Сцилла — дочь штормов, что держала мой корень в морской пене. Не бей в лоб: спереди она парирует.',
                       'The Acropolis by the sea. Scylla is a daughter of storms who held my root in the sea foam. Do not strike head-on: from the front she parries.',
                       'Сцилла пала. Море стихло.', 'Scylla has fallen. The sea is calm.'),
    '24_malkuth': _s('Малкут, Царство, — ветвь, что держала землю. Коснись его знака посреди арены. Он меняет огонь и лёд.',
                     'Malkuth, the Kingdom, is the branch that held the earth. Touch his sign in the middle of the arena. He shifts between fire and ice.'),
    '25_chesed': _s('Хесед, Милость, — ветвь, что держала жизнь. Коснись её знака. Ломай кристаллы вокруг, и защита падёт.',
                    'Chesed, Mercy, is the branch that held life. Touch her sign. Break the crystals around her and her guard will fall.'),
    '26_geburah': _s('Гвура, Строгость, — ветвь, что держала пустоту. Коснись её знака. Не подходи к краю.',
                     'Geburah, Severity, is the branch that held the void. Touch her sign. Stay away from the edge.'),
}

STEP_TEXT_OVERRIDES = {
    '18_ender_dragon': ('Дракон спит над замком в Крае. Подойди — и он поднимется.', 'The dragon sleeps above the End castle in the End realm. Come near and it rises.'),
    '31_wither': ('Иссушитель заперт в святилище в краю Нижнего мира. Подойди — и он поднимется.', 'The Wither is sealed in a sanctum in the Nether realm. Come near and it rises.'),
}

